const KM=1.609344;
function parse(v){const s=v.trim().replace(',', '.');if(s===''||isNaN(Number(s)))return null;return Number(s);}
function fmt(n){return String(Math.round(n*100)/100);}
function run(inId,errId,resId,factor,unit){
 const n=parse(document.getElementById(inId).value);
 const err=document.getElementById(errId);
 const res=document.getElementById(resId);
 if(n===null){err.textContent='Please type a number.';res.textContent='';return;}
 err.textContent='';
 res.textContent=fmt(n*factor)+' '+unit;
}
function wire(btn,inId,errId,resId,factor,unit){
 const go=()=>run(inId,errId,resId,factor,unit);
 document.getElementById(btn).addEventListener('click',go);
 document.getElementById(inId).addEventListener('keydown',e=>{if(e.key==='Enter')go();});
}
wire('tomi','km','kerr','mires',1/KM,'miles');
wire('tokm','mi','merr','kmres',KM,'kilometres');

