const t=document.getElementById('text');
function update(){
 const v=t.value;
 const m=v.trim()===''?[]:v.trim().split(/\s+/);
 document.getElementById('words').textContent=String(m.length);
 document.getElementById('chars').textContent=String(v.length);
 document.getElementById('nospace').textContent=String(v.replace(/\s/g,'').length);
}
t.addEventListener('input',update);
t.addEventListener('change',update);
update();

const d1 = document.getElementById('d1');
const d2 = document.getElementById('d2');
const total = document.getElementById('total');
function rollDie() { return Math.floor(Math.random() * 6) + 1; }
document.getElementById('roll').addEventListener('click', () => {
  const a = rollDie();
  const b = rollDie();
  d1.textContent = String(a);
  d2.textContent = String(b);
  d1.setAttribute('aria-label', 'First die: ' + a);
  d2.setAttribute('aria-label', 'Second die: ' + b);
  total.textContent = 'Total: ' + (a + b);
});

