const billEl=document.getElementById('bill');
const tipEl=document.getElementById('tip');
const peopleEl=document.getElementById('people');
const err=document.getElementById('error');
function update(){
  const bill=parseFloat(billEl.value);
  const tip=parseFloat(tipEl.value);
  const people=parseInt(peopleEl.value,10);
  let msg='';
  if(!(bill>=0)) msg='Enter the bill as a number, 0 or more.';
  else if(!(tip>=0)) msg='Enter the tip percent as a number, 0 or more.';
  else if(!(people>=1)) msg='Enter at least 1 person.';
  err.textContent=msg;
  if(msg){
    document.getElementById('each').textContent='0.00';
    document.getElementById('tipAmt').textContent='0.00';
    document.getElementById('total').textContent='0.00';
    return;
  }
  const tipAmt=bill*tip/100;
  const total=bill+tipAmt;
  document.getElementById('each').textContent=(total/people).toFixed(2);
  document.getElementById('tipAmt').textContent=tipAmt.toFixed(2);
  document.getElementById('total').textContent=total.toFixed(2);
}
for(const el of [billEl,tipEl,peopleEl]){el.addEventListener('input',update);}
update();
